 for(const c of conditions){if(c.type!=='force'||c.regions.every(r=>!meshes[r.mesh].visible))continue;const center=new THREE.Vector3();let n=0;if(c.planarRegion){center.fromArray(planarCorners(c.planarRegion)[0].map((v,k)=>(v+planarCorners(c.planarRegion)[2][k])/2));n=1;}else if(c.cylindricalRegion?.exactCad){const d=c.cylindricalRegion;center.fromArray(cylinderPatchPoint(d,(d.axialMin+d.axialMax)/2,d.startDegrees+d.sweepDegrees/2));n=1;}else for(const r of c.regions){const p=meshes[r.mesh].geometry.attributes.position;for(const t of r.triangles)for(let v=0;v<3;v++){center.add(new THREE.Vector3().fromBufferAttribute(p,t*3+v));n++;}}if(n){center.divideScalar(n);markers.add(new THREE.ArrowHelper(new THREE.Vector3(...c.direction).normalize(),center,scale,0xffac58));}}
