function applyThermalCase(index){const c=caseStore.list()[index];if(!c||c.output.result.kind!=='thermal')throw Error('Choose a saved thermal case');if(c.output.result.contactTransfers?.length&&!c.output.mesh.nodeBodies)throw Error('Contact temperature transfer requires matching body identifiers');const p=getProject();if(!p.sourceModel||JSON.stringify(p.sourceModel)!==JSON.stringify(c.output.input.sourceModel))throw Error('Use the same solid geometry for temperature transfer');api.setStudy({...p.study,kind:'structural',thermalStress:true,temperatureSource:{name:c.name,mesh:{nodes:c.output.mesh.nodes,tetrahedra:c.output.mesh.tetrahedra,...(c.output.mesh.nodeBodies?{nodeBodies:c.output.mesh.nodeBodies}:{})},temperature:c.output.result.temperature}});$('thermal-source-name').textContent=c.name;return api.getSummary();}
window.analysisApi.applyThermalCase=applyThermalCase;
$('thermal-case-apply').onclick=()=>{try{applyThermalCase(Number($('thermal-case').value));}catch(e){status(e.message);}};
$('thermal-case-clear').onclick=()=>{const p=getProject(),study={...p.study};delete study.temperatureSource;api.setStudy(study);$('thermal-source-name').textContent='';};

