$('cylinder-select').onclick=()=>{try{const axis=Number($('cylinder-axis').value),spec={origin:['cylinder-x','cylinder-y','cylinder-z'].map(id=>Number($(id).value)),axis:[[1,0,0],[0,1,0],[0,0,1]][axis],reference:axis===0?[0,1,0]:[1,0,0],radius:Number($('cylinder-radius').value),tolerance:Number($('cylinder-tolerance').value),axialMin:Number($('cylinder-min').value),axialMax:Number($('cylinder-max').value),startDegrees:Number($('cylinder-start').value),sweepDegrees:Number($('cylinder-sweep').value),exactCad:$('cylinder-exact').checked};snapshot();api.selectCylindricalRegion(Number($('cylinder-mesh').value),spec);status('円筒の数値領域を選択しました。');}catch(e){status(e.message);}};
