function restoreCylinderFields(c){$('cylinder-exact').checked=!!c.exactCad;$('cylinder-mesh').value=c.mesh;c.origin.forEach((v,k)=>$(['cylinder-x','cylinder-y','cylinder-z'][k]).value=v);for(const [key,id]of [['radius','cylinder-radius'],['tolerance','cylinder-tolerance'],['axialMin','cylinder-min'],['axialMax','cylinder-max'],['startDegrees','cylinder-start'],['sweepDegrees','cylinder-sweep']])$(id).value=c[key];const length=Math.hypot(...c.axis),axis=c.axis.findIndex(v=>Math.abs(v/length-1)<1e-8);$('cylinder-axis').value=axis<0?'custom':String(axis);}

$('geometry-inspect').onclick=()=>{try{const root=$('geometry-report');root.replaceChildren();for(const r of api.inspectGeometry()){const p=document.createElement('p');p.textContent='#'+r.mesh+' · '+(r.closedEdgeTopology?'辺の閉鎖検査: 合格':'辺の閉鎖検査: 要確認')+' / 寸法 '+r.boundsMm.dimensions.map(v=>v.toPrecision(5)).join(' × ')+' mm / 許容差 '+r.toleranceMm.toPrecision(3)+' mm / 開いた辺 '+r.boundaryEdges+' / 非多様体辺 '+r.nonmanifoldEdges+' / 向きの不一致 '+r.inconsistentWindingEdges+' / 退化 '+r.degenerateTriangles+' / 重複 '+r.duplicateTriangles+' / 接続成分 '+r.components;root.append(p);if(r.problemTriangles.length){const b=document.createElement('button');b.textContent='不備箇所を選択（最大1000枚）';b.onclick=()=>api.selectTriangles(r.mesh,r.problemTriangles);root.append(b);}}}catch(e){status(e.message);}};

