function renderFarField(f){const root=$('result-summary'),caption=document.createElement('p');caption.textContent='遠方界の換算距離 '+(f.referenceDistanceM*1000).toPrecision(5)+' mm / 方向数 '+f.count+' / 0°: '+['+Y','+Z','+X'][f.axis]+' / 最大 '+(f.maxPeakPressurePa*1000).toPrecision(5)+' mPa';root.append(caption);if(f.normalized){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 220 220');svg.setAttribute('role','img');svg.setAttribute('aria-label',language==='en'?'Normalized far-field directivity, 60 dB range':'遠方界の相対指向性、60 dB表示範囲');svg.style.width='100%';svg.style.maxHeight='240px';for(const radius of [30,60,90]){const circle=document.createElementNS(ns,'circle');for(const [k,v]of Object.entries({cx:110,cy:110,r:radius,fill:'none',stroke:'#4a687a'}))circle.setAttribute(k,v);svg.append(circle);}const polygon=document.createElementNS(ns,'polygon');polygon.setAttribute('points',f.samples.map(s=>{const a=s.angleDeg*Math.PI/180,r=90*Math.max(0,1+s.relativeDb/60);return (110+r*Math.cos(a))+','+(110-r*Math.sin(a));}).join(' '));polygon.setAttribute('fill','#65d0c422');polygon.setAttribute('stroke','#77e2d3');polygon.setAttribute('stroke-width','2');svg.append(polygon);for(const [label,x,y]of [['0°',204,114],['90°',100,13],['180°',0,114],['270°',98,215]]){const text=document.createElementNS(ns,'text');text.textContent=label;text.setAttribute('x',x);text.setAttribute('y',y);text.setAttribute('fill','#b8cddd');text.setAttribute('font-size','10');svg.append(text);}root.append(svg);const scale=document.createElement('p');scale.textContent='外周 0 dB / 中間 −20 dB / 内側 −40 dB / 中心 −60 dB';root.append(scale);}else{const p=document.createElement('p');p.textContent='音圧が0のため相対指向性は定義しません。';root.append(p);}const table=document.createElement('table'),head=document.createElement('tr');for(const label of ['°','mPa（ピーク）','dB（RMS）','相対dB']){const th=document.createElement('th');th.textContent=label;head.append(th);}table.append(head);for(const s of f.samples){const row=document.createElement('tr');for(const text of [s.angleDeg.toFixed(1),(s.peakPressurePa*1000).toPrecision(4),s.splDb.toFixed(2),s.relativeDb===null?'—':(Math.abs(s.relativeDb)<.005?0:s.relativeDb).toFixed(2)]){const td=document.createElement('td');td.textContent=text;row.append(td);}table.append(row);}root.append(table);}
async function exteriorAcousticExample(){const g=new THREE.SphereGeometry(5,32,16).toNonIndexed(),d=geometryData(g);d.faceIds.fill(0);setModel([d],language==='en'?'Pulsating sphere reference':'球音源の参照サンプル');g.dispose();sourceModel={kind:'sphere',center:[0,0,0],radius:5};$('mesh-size').value=3;const output=await createExteriorDomain(20-Math.sqrt(3)*5,true),inner=output.mesh.surface.flatMap((f,i)=>f.nodes.every(n=>Math.abs(Math.hypot(...output.mesh.nodes.slice(n*3,n*3+3))-5)<1e-5)?[i]:[]);api.selectTriangles(0,inner);api.addCondition({type:'acousticPressure',value:1});api.setStudy({...getProject().study,kind:'acoustic',frequency:1000,soundSpeed:343,airDensity:1.2,lossFactor:0,exteriorRadiation:true,directivityEnabled:true,directivityAxis:2,directivityPoints:36,directivityDistanceMm:1000,sweep:false,receiverPoint:[0,0,10]});window.viewApi.set({clipEnabled:true,axis:2,position:0,flip:true,opacity:1,hiddenParts:[]});modelName=language==='en'?'Exterior pulsating sphere':'外部放射する球音源';$('name').textContent=modelName;status('半径5 mmの音源に1 Pa、外周半径20 mm。1 m換算の参照音圧は5 mPaです。メッシュ2 mmで精度が改善します。');}
