function renderTransientAcoustic(r){
 const host=$('acoustic-time-results');host.replaceChildren();if(acousticAudioUrl)URL.revokeObjectURL(acousticAudioUrl);acousticFrame=0;
 const label=document.createElement('label'),slider=document.createElement('input'),time=document.createElement('p');label.textContent='表示時刻';slider.type='range';slider.min=0;slider.max=r.snapshots.length-1;const peakIndex=r.receiverPressurePa.reduce((best,v,i)=>Math.abs(v)>Math.abs(r.receiverPressurePa[best])?i:best,0),peakTime=peakIndex*r.timeStep;slider.value=r.snapshots.reduce((best,f,i)=>Math.abs(f.time-peakTime)<Math.abs(r.snapshots[best].time-peakTime)?i:best,0);slider.step=1;slider.setAttribute('aria-label','表示時刻');label.append(slider);host.append(label,time);
 const update=()=>{acousticFrame=Number(slider.value);time.textContent=(r.snapshots[acousticFrame].time*1000).toFixed(4)+' ms / dt '+(r.timeStep*1e6).toPrecision(5)+' µs / 安定上限 '+(r.stableTimeStep*1e6).toPrecision(5)+' µs';showAnalysis();};slider.oninput=update;update();
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 320 120');svg.setAttribute('role','img');svg.setAttribute('aria-label','受音点の音圧波形');svg.style.width='100%';const path=document.createElementNS(svg.namespaceURI,'path');let d='';const stride=Math.max(1,Math.ceil(r.receiverPressurePa.length/600));for(let i=0;i<r.receiverPressurePa.length;i+=stride)d+=(d?' L':'M')+(i/(r.receiverPressurePa.length-1)*320).toFixed(2)+' '+(60-r.receiverPressurePa[i]/(r.receiverPeakPa||1)*55).toFixed(2);path.setAttribute('d',d);path.setAttribute('fill','none');path.setAttribute('stroke','#7ed8d0');svg.append(path);host.append(svg);const caption=document.createElement('p');caption.textContent='受音点の音圧波形 / 横軸: 記録時間 / 縦軸: ±'+r.receiverPeakPa.toPrecision(5)+' Pa';host.append(caption);const wav=acousticWav(r),audio=document.createElement('audio'),download=document.createElement('a'),note=document.createElement('p');acousticAudioUrl=URL.createObjectURL(new Blob([wav.bytes],{type:'audio/wav'}));audio.controls=true;audio.src=acousticAudioUrl;audio.style.width='100%';download.href=acousticAudioUrl;download.download='receiver-normalized.wav';download.textContent='受音点のWAVを保存';note.textContent='再生音はピーク正規化しています。実際の音圧は上のPaを参照。時間の引き伸ばしは行いません。';host.append(audio,download,note);
}
