function renderModal(r){const host=$('modal-results');host.replaceChildren();modalIndex=0;const label=document.createElement('label'),select=document.createElement('select');label.textContent='表示する振動モード';select.setAttribute('aria-label','表示する振動モード');r.modes.forEach((m,i)=>{const o=document.createElement('option');o.value=i;o.textContent='#'+(i+1)+' · '+m.frequencyHz.toFixed(3)+' Hz / residual '+m.residual.toExponential(2);select.append(o);});label.append(select);host.append(label);const note=document.createElement('p');note.textContent='最大変位1 mmの振動形状。実際の応答振幅ではありません。集中質量Tet4 / 部分空間反復 '+r.iterations+' / 部品質量 '+r.totalMassKg.toPrecision(5)+' kg';host.append(note);select.onchange=()=>{modalIndex=Number(select.value);showAnalysis();};showAnalysis();}
