async function createModalAcoustic(){const saved=caseStore.list()[Number($('vibration-case').value)];if(!saved)throw Error('固有振動を計算してケースに保存してください。');const output=prepareCaseView(saved),r=output.result,index=Number($('vibration-mode').value)-1,mode=r.modes?.[index],solid=output.input.sourceModel;if(r.kind!=='modal'||!Number.isInteger(index)||!mode||solid?.kind!=='box')throw Error('直方体部品の有効な振動モードを選んでください。');const source={name:saved.name,modeIndex:index,mesh:{nodes:output.mesh.nodes,tetrahedra:output.mesh.tetrahedra},bounds:[...solid.bounds],displacement:[...mode.displacement],frequencyHz:mode.frequencyHz,amplitudeMm:Number($('vibration-amplitude').value),phaseDeg:Number($('vibration-phase').value)};validateVibrationSource(source);api.loadProject({...output.input,study:{kind:'structural',modalAnalysis:false},conditions:[]});$('mesh-size').value=8*Math.max(1,Math.max(...solid.bounds.slice(3))/80,Number($('fluid-padding').value)/10);$('solver').value='wasm-pcg';await createExteriorDomain(Number($('fluid-padding').value),true);api.setStudy({...getProject().study,frequency:source.frequencyHz,lossFactor:0,acousticTransient:false,sweep:false,exteriorRadiation:true,directivityEnabled:true,directivityPoints:36,directivityAxis:2,directivityDistanceMm:1000,vibrationSource:source});$('clip-axis').value=0;$('clip-position').value=solid.bounds[0]+solid.bounds[3]/2;$('clip-enabled').checked=true;applyViewSettings();status('振動モードを外部音響の音源に設定しました。解析を実行してください。');}
