function internalOptions(){return {enclosure:[...['x','y','z'].map(k=>Number($('internal-min-'+k).value)),...['x','y','z'].map(k=>Number($('internal-width-'+k).value))],seedPoint:['x','y','z'].map(k=>Number($('internal-seed-'+k).value)),portPlanes:[0,1,2,3,4,5].filter(i=>$('internal-port-'+i).checked)};}
function restoreInternalFields(s){['x','y','z'].forEach((k,i)=>{$('internal-min-'+k).value=s.enclosure[i];$('internal-width-'+k).value=s.enclosure[i+3];$('internal-seed-'+k).value=s.seedPoint[i];});for(let i=0;i<6;i++)$('internal-port-'+i).checked=s.portPlanes.includes(i);}
function internalModelBounds(){const p=getProject(),lo=[Infinity,Infinity,Infinity],hi=[-Infinity,-Infinity,-Infinity];for(const m of p.meshes)for(let i=0;i<m.positions.length;i++){const k=i%3;lo[k]=Math.min(lo[k],m.positions[i]);hi[k]=Math.max(hi[k],m.positions[i]);}const b=[...lo,...hi.map((v,i)=>v-lo[i])];restoreInternalFields({enclosure:b,seedPoint:lo.map((v,i)=>(v+hi[i])/2),portPlanes:internalOptions().portPlanes});}
function renderInternalPorts(mesh){const root=$('internal-ports');root.replaceChildren();const d=mesh?.domainSelection;if(!d)return;const title=document.createElement('p');title.textContent='CAD流体体積 '+d.cadVolumeMm3.toFixed(3)+' mm³ / 除外した空間 '+d.excludedVolumes+' / ポート '+new Set(d.ports.map(p=>p.plane)).size;root.append(title);if(!d.ports.length){const note=document.createElement('p');note.textContent='閉じた内部空間（ポートなし）';root.append(note);}for(const plane of [...new Set(d.ports.map(p=>p.plane))].sort()){const button=document.createElement('button');button.textContent='ポート '+['X−','Y−','Z−','X＋','Y＋','Z＋'][plane]+' を選ぶ';button.onclick=()=>{const p=getProject(),ids=new Set(d.ports.filter(v=>v.plane===plane).map(v=>v.faceTag)),triangles=p.meshes[0].faceIds.flatMap((tag,i)=>ids.has(tag)?[i]:[]);$('setup-view').click();api.selectTriangles(0,triangles);};root.append(button);}if(d.channel){const note=document.createElement('p');note.textContent=(d.channel.radiusMm?'CADで確認した円形直管 / 半径 '+d.channel.radiusMm.toPrecision(5)+' mm / 長さ ':'CADで確認した角形直管 / 幅 '+d.channel.widthMm.map(v=>v.toPrecision(5)).join(' × ')+' mm / 長さ ')+(d.channel.lengthM*1000).toPrecision(5)+' mm';root.append(note);}}
async function createInternalDomain(){if(!$('cancel-run').disabled)throw Error('先に実行中の計算を中止してください。');const original=api.exportProject(),solid=original.sourceModel?.kind==='fluidDomain'?original.sourceModel.solid:original.sourceModel,source=internalFluidSource({...original,sourceModel:solid},internalOptions());api.loadProject({...original,sourceModel:source,study:{kind:'fluidDomain'},conditions:[],selection:original.meshes.map(()=>[])});const revision=projectRevision;$('mesh-run').disabled=$('solve-run').disabled=true;$('cancel-run').disabled=false;try{const output=await analysis.generateMesh({size:Number($('mesh-size').value),method:'wasm-pcg'});if(projectRevision!==revision)throw Error('Inputs changed during calculation; run again');const mesh=output.mesh,data={positions:mesh.surface.flatMap(f=>f.nodes.flatMap(i=>mesh.nodes.slice(3*i,3*i+3))),faceIds:mesh.surface.map(f=>f.faceTag),kind:'gmsh-surface',sourceHash:mesh.sourceHash},study=mesh.domainSelection.channel?{kind:'channelFlow',flowAxis:mesh.domainSelection.channel.axis,pressureDropPa:Number($('flow-pressure-drop').value),dynamicViscosity:Number($('flow-viscosity').value),fluidDensity:Number($('flow-density').value),fluidSoundSpeed:Number($('flow-sound-speed').value)}:{kind:'fluidDomain'};api.loadProject({...output.input,name:language==='en'?'Internal fluid domain':'内部流体領域',study,meshes:[data],selection:[[]],conditions:[]});lastAnalysis={...output,input:api.exportProject()};renderInternalPorts(mesh);$('mesh-summary').textContent=mesh.summary.nodeCount+' 節点 / '+mesh.summary.elementCount+' 四面体 / '+mesh.summary.volumeMm3.toFixed(3)+' mm³';status('内部流体領域を生成しました。ポートを確認してください。');return lastAnalysis;}catch(e){if(projectRevision===revision)api.loadProject(original);throw e;}finally{$('mesh-run').disabled=false;$('solve-run').disabled=$('physics').value==='fluidDomain';$('cancel-run').disabled=true;}}
async function internalFluidExample(){if(!$('cancel-run').disabled)throw Error('先に実行中の計算を中止してください。');const original=api.exportProject(),tube={kind:'tube',center:[0,0,0],axis:1,outerRadius:12,innerRadius:8,length:60};api.loadProject({...getProject(),sourceModel:tube,study:{kind:'fluidDomain'},materialProperties:{},conditions:[]});const revision=projectRevision;$('mesh-run').disabled=$('solve-run').disabled=true;$('cancel-run').disabled=false;let output;try{output=await analysis.generateMesh({size:4,method:'wasm-pcg'});if(revision!==projectRevision)throw Error('Inputs changed during calculation; run again');}catch(e){if(projectRevision===revision)api.loadProject(original);throw e;}finally{$('mesh-run').disabled=false;$('solve-run').disabled=$('physics').value==='fluidDomain';$('cancel-run').disabled=true;}const mesh=output.mesh;api.loadProject({...output.input,name:language==='en'?'Hollow tube · outer Ø24 / inner Ø16 × 60 mm':'中空管 · 外径24 / 内径16 × 60 mm',meshes:[{positions:mesh.surface.flatMap(f=>f.nodes.flatMap(i=>mesh.nodes.slice(3*i,3*i+3))),faceIds:mesh.surface.map(f=>f.faceTag),kind:'gmsh-surface',sourceHash:mesh.sourceHash}],selection:[[]],conditions:[]});restoreInternalFields({enclosure:[-12,-30,-12,24,60,24],seedPoint:[0,0,0],portPlanes:[1,4]});$('mesh-size').value=2;$('solver').value='wasm-pcg';$('flow-pressure-drop').value=.01;$('flow-viscosity').value=.001;$('flow-density').value=1000;$('flow-sound-speed').value=1480;$('adaptive-run').checked=false;return createInternalDomain();}
$('internal-bounds').onclick=internalModelBounds;$('internal-create').onclick=()=>createInternalDomain().catch(e=>status(e.message));$('internal-fluid-demo').onclick=()=>internalFluidExample().catch(e=>status(e.message));window.analysisApi.loadInternalFluidExample=internalFluidExample;

function updateResultSlice(){
 const previous=analysisLayer.children.find(o=>o.userData.isResultSlice);if(previous){previous.geometry.dispose();previous.material.dispose();analysisLayer.remove(previous);}$('section-summary').textContent='';if(!resultSliceContext||!$('clip-enabled').checked||!$('result-section').checked||!analysisLayer.visible)return;
 const c=resultSliceContext,s=tetrahedronSection(c.mesh,{axis:Number($('clip-axis').value),position:Number($('clip-position').value),flip:$('clip-flip').checked,displayNodes:c.displayNodes});if(!s.positions.length)return;const colors=[],field=$('result-field').value;
 for(const v of s.samples){const scalar=values=>v.nodes.reduce((sum,node,i)=>sum+v.weights[i]*values[node],0),vector=values=>[0,1,2].map(k=>v.nodes.reduce((sum,node,i)=>sum+v.weights[i]*values[3*node+k],0));let value;
 if(c.result.kind==='acoustic'){const real=scalar(c.result.real),imag=scalar(c.result.imag),peak=Math.hypot(real,imag);value=field==='phase'?Math.atan2(imag,real):field==='spl'?20*Math.log10(Math.max(peak/Math.SQRT2,1e-12)/c.result.referencePressurePa):peak;}
 else if(c.result.kind==='modal'||c.result.kind==='elastic'&&field==='displacement')value=Math.hypot(...vector(c.mode?.displacement||c.result.displacement));
 else if(c.result.kind==='channelFlow'&&field==='speed')value=Math.hypot(...vector(c.result.velocity));else value=scalar(c.values);
 const color=new THREE.Color().setHSL((1-(c.max>c.min?Math.max(0,Math.min(1,(value-c.min)/(c.max-c.min))):0))*.65,.8,.5);colors.push(color.r,color.g,color.b);}
 const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(s.positions,3));geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geometry.computeVertexNormals();const opacity=Number($('model-opacity').value),cap=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({vertexColors:true,side:THREE.DoubleSide,roughness:.65,opacity,transparent:opacity<1}));cap.userData.isResultSlice=true;cap.userData.resultPhysicalPositions=s.physicalPositions;cap.userData.resultBodyIndices=s.bodyIndices;cap.userData.resultElements=s.elementIndices;analysisLayer.add(cap);$('section-summary').textContent='解析断面: '+s.elementIndices.length+' 三角形 / 計算場の補間表示（条件設定面ではありません）';
}

$('planar-select').onclick=()=>{try{const mesh=selection.findIndex(s=>s.size),spec={axis:Number($('planar-axis').value),position:Number($('planar-position').value),min:[Number($('planar-min-u').value),Number($('planar-min-v').value)],max:[Number($('planar-max-u').value),Number($('planar-max-v').value)]};api.selectPlanarRegion(mesh<0?0:mesh,$('planar-rotate').checked?planarRegionFromEuler(spec.axis,spec.position,['planar-angle-x','planar-angle-y','planar-angle-z'].map(id=>Number($(id).value)),spec.min,spec.max):spec);status('矩形領域を選択しました。条件を追加してください。');}catch(e){status(e.message);}};

function cylindricalCadExample(){demo();api.setMaterialProperties({youngModulus:1e9,poissonRatio:0,density:1000});api.setStudy({...getProject().study,kind:'structural',modalAnalysis:false,thermalStress:false,gravityEnabled:false});const spec={origin:[0,0,0],axis:[0,1,0],reference:[1,0,0],radius:12,tolerance:.3,exactCad:true,startDegrees:0,sweepDegrees:360,axialMin:-30,axialMax:-20};api.selectCylindricalRegion(0,spec);api.addCondition({type:'fixed'});api.selectCylindricalRegion(0,{...spec,axialMin:-10,axialMax:10,startDegrees:315,sweepDegrees:90});api.addCondition({type:'force',value:123,direction:[-1,0,0]});$('mesh-size').value=4;$('solver').value='wasm-pcg';$('adaptive-run').checked=false;$('deform-scale').value=20;modelName=language==='en'?'Exact cylindrical CAD patches':'円筒部分領域のCAD分割';$('name').textContent=modelName;status('円筒の帯を固定し、90度の部分領域に123 Nを掛けます。CAD境界に沿ってメッシュを切ります。');}
$('cylindrical-cad-demo').onclick=cylindricalCadExample;window.analysisApi.loadCylindricalCadExample=cylindricalCadExample;
